3D movie poster card showcase with glow effect. 16s, 1920x1080, SILENT. Pure black background. Three portrait posters appear one at a time as 3D rocking cards. Each card has: animated edge glow (box-shadow pulse), a moving specular highlight sweep across the poster, and a soft ambient glow behind the card. The glow color differs per card — Turing: amber/gold, Sherlock: cool blue, Hamlet: warm red. Card rocks side to side (perspective rotateY oscillation ±20deg). Name below. No small text
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}
/* ambient glow behind card */
glow-bg{
position:absolute
width:500px;height:700px
border-radius:50%
filter:blur(80px)
opacity:0
z-index:0
}
card-stage{
position:absolute;z-index:5
display:flex;flex-direction:column;align-items:center
opacity:0
}
/* 3D rocking card */
card-wrap{
width:300px;height:450px
position:relative;z-index:1
}
/* card face */
card-face{
width:100%;height:100%
border-radius:8px
overflow:hidden
position:relative
/* edge glow via box-shadow — animated per card */
}
card-face img{
width:100%;height:100%
object-fit:cover;object-position:center top
display:block
}
/* specular highlight sweep */
card-face::after{
content:""
position:absolute;top:0;left:-60%
width:40%;height:100%
background:linear-gradient(105deg
transparent 30%
rgba(255,255,255,0.18) 50%
transparent 70%)
animation:specular 2.4s ease-in-out infinite alternate
pointer-events:none
z-index:2
}
@keyframes specular{
from{left:-60%;}
to  {left:120%;}
}
/* per-card glow colors */
#s1 .card-face{
box-shadow
0 0 0 1px rgba(255,200,80,0.4)
0 0 30px rgba(255,180,40,0.35)
0 20px 60px rgba(0,0,0,0.8)
animation:glowAmber 2s ease-in-out infinite alternate
}
#s1 .glow-bg{background:radial-gradient(ellipse,rgba(255,160,30,0.45),transparent 70%);}
@keyframes glowAmber{
from{box-shadow:0 0 0 1px rgba(255,200,80,0.3),0 0 20px rgba(255,180,40,0.25),0 20px 60px rgba(0,0,0,0.8);}
to  {box-shadow:0 0 0 2px rgba(255,220,100,0.6),0 0 50px rgba(255,200,60,0.50),0 20px 60px rgba(0,0,0,0.8);}
}
#s2 .card-face{
box-shadow
0 0 0 1px rgba(80,160,255,0.4)
0 0 30px rgba(60,140,255,0.35)
0 20px 60px rgba(0,0,0,0.8)
animation:glowBlue 2s ease-in-out infinite alternate
}
#s2 .glow-bg{background:radial-gradient(ellipse,rgba(40,120,255,0.40),transparent 70%);}
@keyframes glowBlue{
from{box-shadow:0 0 0 1px rgba(80,160,255,0.3),0 0 20px rgba(60,140,255,0.25),0 20px 60px rgba(0,0,0,0.8);}
to  {box-shadow:0 0 0 2px rgba(120,190,255,0.6),0 0 50px rgba(80,160,255,0.50),0 20px 60px rgba(0,0,0,0.8);}
}
#s3 .card-face{
box-shadow
0 0 0 1px rgba(200,50,50,0.4)
0 0 30px rgba(180,30,30,0.35)
0 20px 60px rgba(0,0,0,0.8)
animation:glowRed 2s ease-in-out infinite alternate
}
#s3 .glow-bg{background:radial-gradient(ellipse,rgba(180,30,30,0.40),transparent 70%);}
@keyframes glowRed{
from{box-shadow:0 0 0 1px rgba(200,50,50,0.3),0 0 20px rgba(180,30,30,0.25),0 20px 60px rgba(0,0,0,0.8);}
to  {box-shadow:0 0 0 2px rgba(240,80,80,0.6),0 0 50px rgba(220,50,50,0.50),0 20px 60px rgba(0,0,0,0.8);}
}
role-label{
margin-top:22px;text-align:center
opacity:0;z-index:5
}
role-name{
font-family:'Playfair Display',Georgia,serif
font-size:44px;font-weight:700
color:#f0ece4;line-height:.90;letter-spacing:-.01em
}
#open-fade,#close-fade{
position:absolute;inset:0;z-index:50
background:#000;pointer-events:none
}
#open-fade{opacity:1;}#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="scene">
<div id="open-fade"></div>
<div id="close-fade"></div>
<div class="card-stage" id="s1">
<div class="glow-bg"></div>
<div class="card-wrap" id="w1">
<div class="card-face"><img src="{{p1}}" alt=""></div>
</div>
<div class="role-label" id="l1"><div class="role-name">Alan Turing</div></div>
</div>
<div class="card-stage" id="s2">
<div class="glow-bg"></div>
<div class="card-wrap" id="w2">
<div class="card-face"><img src="{{p2}}" alt=""></div>
</div>
<div class="role-label" id="l2"><div class="role-name">Sherlock Holmes</div></div>
</div>
<div class="card-stage" id="s3">
<div class="glow-bg"></div>
<div class="card-wrap" id="w3">
<div class="card-face"><img src="{{p3}}" alt=""></div>
</div>
<div class="role-label" id="l3"><div class="role-name">Hamlet</div></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
function startRock(wrap){
gsap.set(wrap,{transformPerspective:900,rotateX:5,rotateY:-20})
gsap.to(wrap,{rotateY:20,rotateX:3,duration:1.2,ease:'sine.inOut',repeat:-1,yoyo:true})
}
var tl=gsap.timeline()
tl.to('#open-fade',{opacity:0,duration:0.45,ease:'power2.out'},0.0)
/* CARD 1 — Turing */
tl.set('#s1',{opacity:1},0.4)
tl.to('#s1 .glow-bg',{opacity:1,duration:0.6,ease:'power2.out'},0.4)
tl.to('#s1',{scale:1,duration:0.65,ease:'back.out(1.2)',startAt:{scale:0.80}},0.4)
tl.to('#l1',{opacity:1,y:0,duration:0.45,ease:'power3.out',startAt:{y:12}},0.75)
tl.call(function(){startRock(document.querySelector('#w1'));},null,0.4)
tl.to('#s1 .glow-bg',{opacity:0,duration:0.4},4.5)
tl.to('#l1',{opacity:0,duration:0.3,ease:'power2.in'},4.5)
tl.to('#s1',{opacity:0,scale:0.84,duration:0.38,ease:'power2.in'},4.55)
tl.call(function(){gsap.killTweensOf('#w1');},null,4.9)
tl.set('#s1',{opacity:0},4.95)
/* CARD 2 — Sherlock */
tl.set('#s2',{opacity:1},4.9)
tl.to('#s2 .glow-bg',{opacity:1,duration:0.6,ease:'power2.out'},4.9)
tl.to('#s2',{scale:1,duration:0.65,ease:'back.out(1.2)',startAt:{scale:0.80}},4.9)
tl.to('#l2',{opacity:1,y:0,duration:0.45,ease:'power3.out',startAt:{y:12}},5.25)
tl.call(function(){startRock(document.querySelector('#w2'));},null,4.9)
tl.to('#s2 .glow-bg',{opacity:0,duration:0.4},9.5)
tl.to('#l2',{opacity:0,duration:0.3,ease:'power2.in'},9.5)
tl.to('#s2',{opacity:0,scale:0.84,duration:0.38,ease:'power2.in'},9.55)
tl.call(function(){gsap.killTweensOf('#w2');},null,9.9)
tl.set('#s2',{opacity:0},9.95)
/* CARD 3 — Hamlet */
tl.set('#s3',{opacity:1},9.9)
tl.to('#s3 .glow-bg',{opacity:1,duration:0.6,ease:'power2.out'},9.9)
tl.to('#s3',{scale:1,duration:0.65,ease:'back.out(1.2)',startAt:{scale:0.80}},9.9)
tl.to('#l3',{opacity:1,y:0,duration:0.45,ease:'power3.out',startAt:{y:12}},10.25)
tl.call(function(){startRock(document.querySelector('#w3'));},null,9.9)
tl.to('#s3 .glow-bg',{opacity:0,duration:0.4},14.5)
tl.to('#l3',{opacity:0,duration:0.3,ease:'power2.in'},14.5)
tl.to('#s3',{opacity:0,scale:0.84,duration:0.38,ease:'power2.in'},14.55)
tl.to('#close-fade',{opacity:1,duration:0.65,ease:'power2.inOut'},14.7)
tl.set('#close-fade',{opacity:1},15.5)
})
</script>
</body>
</html>
```
